import { createWriteStream, readFileSync } from "fs"
import { promisify } from 'util';

import { sportNameMap } from "../sportNameMap.js";
import { marketNameMap } from "../marketNameMap.js";
import { stripTeamName } from "../util/stripTeamName.js";
import { translateKeywords } from '../util/translateKeywords.js';

// generated by chatGPT https://chatgpt.com/c/a9300588-42f8-40ee-bff4-b00c945cee1e
function convDatetimeToISO(dateStr){
  
  const parseDateStr = (dateStr) => {
    let date;
    const [dayOrKeyword, rest] = dateStr.split(' ', 2);
    
    if (dayOrKeyword.toLowerCase() === "today") {
      date = new Date();
    } else if (dayOrKeyword.toLowerCase() === "tomorrow") {
      date = new Date();
      date.setDate(date.getDate() + 1);
    } else {
      // Split the string further for day, month, and time
      const [day, month, time] = dateStr.split(/[\s:]+/);
      const [hours, minutes] = rest.split(':');
  
      const currentYear = new Date().getFullYear();
      const monthIndex = new Date(`${month} 1, ${currentYear}`).getMonth();
  
      date = new Date(currentYear, monthIndex, parseInt(day), parseInt(hours), parseInt(minutes), 0, 0);
      return date;
    }
  
    const [hours, minutes] = rest.split(':');
    date.setHours(parseInt(hours));
    date.setMinutes(parseInt(minutes));
    date.setSeconds(0);
    date.setMilliseconds(0);
  
    return date;
  };
  
  const date = parseDateStr(dateStr);
  // Format the date as ISO 8601
  return date.toISOString();
}

export async function scrapeMatchURL(data, browser, book, i){
  
  let page = await browser.newPage();
  await page.setViewport(book.viewport);
  await page.setUserAgent('Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36');
  await page.setExtraHTTPHeaders({ 'Accept-Language': 'en-US,en;q=0.9' });
  await page.goto(book.urls[i], {waitUntil:'domcontentloaded'});
  const bookAbbrev = book.abbrev; 
  // open a file for logging
  const logFilePath = `books/${bookAbbrev}/log.txt`
  const log = createWriteStream(logFilePath, {flags: 'a'});
  // load the book-specific mappings from json files
  const sportNameMappingPath = `books/${bookAbbrev}/sportNameMapping.json`;
  let sportNameMapping;
  try{
    sportNameMapping = Object.freeze(JSON.parse(readFileSync(sportNameMappingPath)));
    if(!sportNameMapping){ throw error(); }
  } catch (error){
    log.write(`Failure! Cannot open file ${sportNameMappingPath} or incorrect JSON format\n`);
  }
  const marketNameMappingPath = `books/${bookAbbrev}/marketNameMapping.json`;
  let marketNameMapping;
  try{
    marketNameMapping = Object.freeze(JSON.parse(readFileSync(marketNameMappingPath)));
    if(!marketNameMapping){ throw error(); }
  } catch (error){
    log.write(`Failure! Cannot open file ${marketNameMappingPath} or incorrect JSON format\n`);
  }

  try{
//console.log('data: ');
//console.log(JSON.stringify(data, null, 2));

    let valid = undefined;
    let empty = undefined;
    let count = 0;
    while(!valid && !empty && count < 20){
      valid = await page.$('div.sport-6000');
      empty = await page.$('div.osg-empty');
      count++;
      await new Promise(resolve => setTimeout(resolve, 100));
    }
    if(empty){
      log.write(`Failure! There is an element with class div.osg-empty under this url: ${await page.url()}. Probably past match\n`);
      return 10;
    }
    if(!valid){
      log.write(`Critical Failure! No element with class div.sport-6000. Probably invalid url ${await page.url()}\n`);
      return -1;
    }
    let selector, el, mapping;
    // get sport
    selector = 'div.osg-coupon__breadcrumbs a';
    await page.waitForSelector(selector);
    const breadcrumbs = await page.$$eval(selector, els => els.map(e => e.textContent));
    let sportName = breadcrumbs[breadcrumbs.length-2].trim();
    mapping = sportNameMapping.find( m => m.specificName === sportName);
    if(mapping){
      sportName = sportNameMap[mapping.globalID];
    } else{
      log.write(`Failure! sportName Mapping of '${sportName}' does not exist in ${sportNameMappingPath}\n`);
      return 20;
    }
//console.log('>>>>>>>>>>>>>>> scraped sportName: ' + sportName);
    let sport = data.sports.findLast(s => s.name === sportName);
    if(!sport){
      /* sport is new */
      data.sports.push({ name: sportName, matches: [] });
      sport = data.sports.findLast(s => s.name === sportName);
    }
//console.log('sport: ');
//console.log(JSON.stringify(sport, null, 2));

    // get tournament
    // let tournamentName = breadcrumbs[breadcrumbs.length-1].trim();
    // mapping = tournamentNameMapping.find( m => m.specificName === tournamentName);
    // if(mapping){
    //   tournamentName = tournamentNameMap[mapping.globalID];;
    // } else{
    //   log.write(`Failure! tournamentName Mapping of '${tournamentName}' does not exist in ${tournamentNameMappingPath}\n`);
    //   return;
    // }
//console.log('>>>>>>>>>>>>>>> scraped tournamentname: ' + tournamentName);
    // let tournament = sport.tournaments.findLast(t => t.name === tournamentName );
    // if(!tournament){
    //   /* tournament is new */
    //   sport.tournaments.push({ name: tournamentName, matches: [] });
    //   tournament = sport.tournaments.findLast(t => t.name === tournamentName);
    // }
//console.log('tournament: ');
//console.log(JSON.stringify(tournament, null, 2));

    // get teamHome, teamAway
    selector = 'div.osg-coupon h1';
    const teams = await page.$eval(selector, e => e.textContent.split(' - ') );
    const teamHome = stripTeamName(teams[0]);
    const teamAway = stripTeamName(teams[1]);
//console.log('>>>>>>>>>>>>>>> scraped teamHome: ' + teamHome);
//console.log('>>>>>>>>>>>>>>> scraped teamAway: ' + teamAway);
    
    // get datetime, mode
    selector = 'div.osg-coupon span';
    el = await page.$eval(selector, e => e.textContent.trim().replace(/\u00a0/, '\u0020'));
    const datetime = convDatetimeToISO(el);
//console.log('>>>>>>>>>>>>>>> scraped datetime: ' + datetime);

    let match = sport.matches.findLast(m =>
        (
          m.datetime === datetime || (Math.abs( (new Date(m.datetime)) - (new Date(datetime)) ) <= 3*60*60*1000) // maximum of 3h difference is allowed
        )
        &&
        (
          m.teamHome === teamHome &&
          m.teamAway === teamAway
        )
        ||
        ( 
          m.teamHome === teamAway && // inverted Home/Away ordering, but still the same datetime => the same event
          m.teamAway === teamHome
        )
    )
    if(!match){
      log.write(`Warning! This match could not yet find a match in data_out.json: ${teamHome}, ${teamAway}, ${datetime}\n`);
      /* match is new */
      sport.matches.push({ 
        teamHome: teamHome,
        teamAway: teamAway,
        datetime: datetime,
        urls: [],
        markets: []
      });
      match = sport.matches.findLast(m =>
          m.teamHome === teamHome &&
          m.teamAway === teamAway &&
          m.datetime === datetime
      );
    }
    match.urls.push({book: 'Lsbet', url: await page.url()});
//console.log('match: ');
//console.log(JSON.stringify(match, null, 2));

    // GET ALL THE MARKETS > ODDS > COEFS FOR THIS MATCH
    let market, odd, coef;
    selector = 'div.osg-coupon__market';
    let marketHandles = await page.$$(selector);
//console.log(`$$${selector} length: ${marketHandles.length}`);
    for(const marketHandle of marketHandles){
      // get marketName
      selector = 'h4';
      let marketName = await marketHandle.$eval(selector, e => e.textContent.trim());
      mapping = marketNameMapping.find( m => m.specificName === marketName);
      if(mapping){
        marketName = marketNameMap[mapping.globalID];
      } else{
        log.write(`Warning! marketName Mapping of '${marketName}' does not exist in ${marketNameMappingPath}\n`);
        continue;
      }
//console.log('>>>>>>>>>>>>>>> scraped marketName: ' + marketName);
      market = match.markets.findLast(m => m.name === marketName);
      if(!market){
        match.markets.push({name: marketName, odds: []});
        market = match.markets.findLast(m => m.name === marketName);
      }
//console.log('market: '
//console.log(JSON.stringify(market, null, 2));
      // get odds
      selector = 'div.osg-coupon__market-outcomes div[role="button"]';
      const oddHandles = await marketHandle.$$(selector);
//console.log(`$$${selector} length: ${oddHandles.length}`);
      for(const oddHandle of oddHandles){
        selector = 'span';
        const NameValue = await oddHandle.$$eval(selector, es => es.map(e => e.textContent));
        let oddName = stripTeamName(NameValue[0]);
        if(marketName.includes(marketNameMap['TR'])){
          oddName = translateKeywords(oddName);
        }
        if ( market.name === 'Correct score' && market.teamHome === teamAway && market.teamAway === teamHome){ // in case of CS market and flipped teamNames, the oddNames in the form of '2:0', etc. need to be flipped as well
          const [left, right] = oddName.split(':');
          oddName = `${right}:${left}`;
        }
//console.log('>>>>>>>>>>>>>>> scraped oddName: ' + oddName);
        odd = market.odds.findLast(o => o.name === oddName);
        if(!odd){
          market.odds.push({name: oddName, coefs: []})
          odd = market.odds.findLast(o => o.name === oddName);
        }
        const value = parseFloat(NameValue[1]);
//console.log('>>>>>>>>>>>>>>> scraped value: ' + value);
        coef = odd.coefs.findLast(c => c.book === 'Lsbet');
        if(!coef){
          odd.coefs.push({"timestamp(scraped)":new Date(), book: 'Lsbet', value: value});
        }
//console.log('market: ');
//console.log(JSON.stringify(market, null, 2));
      }
    }

  log.write(`Success! scraping a match from ${await page.url()}\n`);
  return 0;    

  } catch (error){
    log.write(`Critical Failure! scraping a match from ${await page.url()}\n`);
    return -1;
  } finally{
    try{
      await page?.close()
    } catch{}
    await promisify(log.end).bind(log);
  }
  
}